const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
for (let i = 1; i <= 3; i++) {
  console.log(`step ${i} of 3 (port ${process.env.PORT})`);
  await sleep(500);
}
console.log('done ✓');

try {
  await kai.notify('Hello from Node through the kai module', { title: 'Languages demo', level: 'info' });
  console.log('active environment:', await kai.env.active());
  console.log('environments:', (await kai.env.list()).join(', '));
  console.log('commands registered:', (await kai.commands()).length);
} catch (error) {
  console.log('Kai app not reachable:', error.message);
}
